function hmacSha256(key,msg){
  var k=strToBytes(key);
  if(k.length>64)k=sha256bytes(k);
  while(k.length<64)k.push(0);
  var ipad=[],opad=[];
  for(var i=0;i<64;i++){ipad.push(k[i]^0x36);opad.push(k[i]^0x5c);}
