// ==========================================
// 2. CONFIGURAÇÕES E CREDENCIAIS GLOBAIS
// ==========================================
const staticData = $getWorkflowStaticData('global');
const now = Math.floor(Date.now() / 1000);

const PARTNER_ID   = '2036495';
const PARTNER_KEY  = 'shpk484d63747246746b51744d69774445786c4b4a7363615156687448675379';
const SHOP_ID      = '762290009';

let REFRESH_TOKEN  = staticData.saved_refresh_token || '4849644c7a6263554e674d684464674e';
let accessToken = staticData.access_token;
let tokenTimestamp = staticData.token_timestamp || 0;

// ==========================================
// 3. RENOVAÇÃO INVISÍVEL DO TOKEN
// ==========================================
// Se não tiver token ou já tiver passado 3 horas (10800 seg), renova!
if (!accessToken || (now - tokenTimestamp > 10800)) {
    const authPath = '/api/v2/auth/access_token/get';
    const authBaseStr = PARTNER_ID + authPath + now;
    const authSign = hmacSha256(PARTNER_KEY, authBaseStr);

    const response = await this.helpers.httpRequest({
        method: 'POST',
        url: `https://partner.shopeemobile.com${authPath}?partner_id=${PARTNER_ID}&timestamp=${now}&sign=${authSign}`,
        body: {
            refresh_token: REFRESH_TOKEN,
            partner_id: parseInt(PARTNER_ID),
            shop_id: parseInt(SHOP_ID)
        },
        json: true
    });

    if (response.access_token) {
        accessToken = response.access_token;
        staticData.access_token = accessToken;
        staticData.token_timestamp = now;
        if (response.refresh_token) {
            staticData.saved_refresh_token = response.refresh_token;
        }
    } else {
        throw new Error('Erro ao renovar token. Resposta: ' + JSON.stringify(response));
    }
}

// ==========================================
// 4. PREPARAR A BUSCA DAS AVALIAÇÕES
// ==========================================
const pathGetComment = '/api/v2/product/get_comment';
const baseStrGetComment = PARTNER_ID + pathGetComment + now + accessToken + SHOP_ID;
const signGetComment = hmacSha256(PARTNER_KEY, baseStrGetComment);

// BLINDAGEM: cursor precisa ser um inteiro >= 0. Qualquer sujeira gravada em
// execuções antigas (NaN, string inválida, negativo) é saneada para 0 aqui,
// senão a API recebe 'cursor=NaN' e o fluxo trava em erro para sempre.
const cursorSaneado = Number(staticData.currentCursor);
if (!Number.isInteger(cursorSaneado) || cursorSaneado < 0) {
    staticData.currentCursor = 0;
}
const currentCursorValue = staticData.currentCursor.toString();

return [{
    json: {
        partner_id: PARTNER_ID,
        shop_id: SHOP_ID,
        access_token: accessToken,
        timestamp: now,
        sign: signGetComment,
        cursor: currentCursorValue
    }
}];

// Captura a resposta da Shopee vinda do HTTP Request
const responseData = $input.first().json.response || {};
const ratings = responseData.item_comment_list || [];

// ==========================================
// 1. GERENCIAMENTO DE MEMÓRIA (CURSOR)
// ==========================================
const staticData = $getWorkflowStaticData('global');

// Cursor que ESTA execução acabou de usar na busca ('Gerar Autenticação' lê o
// staticData mas não o altera, então ele ainda contém o valor desta página).
const cursorUsado = Number(staticData.currentCursor) || 0;

// BLINDAGEM DO AVANÇO DE PÁGINA — só avança se TODAS as condições valem:
//  1. more === true          → a Shopee afirma que existe próxima página;
//  2. next_cursor é inteiro > 0 → cursor vazio/'0'/não numérico volta ao topo
//     (parseInt cego aqui gravava NaN e travava todas as execuções seguintes);
//  3. next_cursor !== cursorUsado → se a API repetir o cursor atual, avançar
//     'no mesmo lugar' faria o gatilho de 4h reler esta página para sempre.
// Qualquer condição falhando → reset para 0 (recomeça do topo na próxima run).
const proximoCursor = Number(responseData.next_cursor);
const deveAvancar =
  responseData.more === true &&
  Number.isInteger(proximoCursor) &&
  proximoCursor > 0 &&
  proximoCursor !== cursorUsado;

staticData.currentCursor = deveAvancar ? proximoCursor : 0;

// ==========================================
// 2. FILTRAGEM DE AVALIAÇÕES SEM RESPOSTA
// ==========================================
const semResposta = ratings.filter(r => !r.comment_reply);

if (semResposta.length === 0) {
  // Retornar array vazio [] faz o n8n PARAR o fluxo aqui sem erro.
  // O cursor da próxima página já ficou salvo acima.
  return [];
}

// Retorna as avaliações legítimas que precisam de resposta
return semResposta.map(r => ({ json: r }));

const templates = [
  'Olá! Ficamos muito tristes com sua experiência. Pedimos desculpas pelo ocorrido e gostaríamos de entender melhor o que aconteceu. Por favor, entre em contato com nosso chat para que possamos resolver isso rapidamente. Sua satisfação é nossa prioridade! 🙏',
  'Olá! Sentimos muito que sua experiência não foi como esperávamos. Trabalhamos para oferecer o melhor serviço, e sua avaliação nos ajuda a melhorar. Entre em contato conosco pelo chat para resolvermos juntos. Obrigado pela sinceridade!',
  'Olá! Pedimos desculpas pela experiência negativa. Vamos investigar o que aconteceu e tomar as devidas providências. Contamos com sua compreensão e esperamos ter a chance de surpreendê-lo(a) positivamente em uma próxima oportunidade! 💙'
];

// Processa todas as avaliações recebidas na lista
return $input.all().map(item => {
  const resposta = templates[Math.floor(Math.random() * templates.length)];
  return { 
    json: { 
      ...item.json, 
      resposta_gerada: resposta 
    } 
  };
});

const templates = [
  'Olá! Muito obrigado pela sua avaliação! 😊 Fico muito feliz que tenha gostado do produto e do nosso atendimento. Esperamos receber sua visita novamente em breve! 🛍️',
  'Obrigado pela avaliação 5 estrelas! 🌟 É uma satisfação enorme saber que você ficou contente com sua compra. Conte conosco sempre! Até a próxima!',
  'Que alegria receber sua avaliação! Obrigado por escolher nossa loja. Trabalhamos muito para oferecer produtos de qualidade e um ótimo atendimento. Volte sempre! 💚',
  'Muito obrigado pelo carinho! 🙏 Sua satisfação é a nossa maior recompensa. Estamos sempre à disposição para o que precisar. Nos vemos na próxima compra! 😄'
];

// Processa todas as avaliações recebidas na lista
return $input.all().map(item => {
  const resposta = templates[Math.floor(Math.random() * templates.length)];
  return { 
    json: { 
      ...item.json, 
      resposta_gerada: resposta 
    } 
  };
});

