// ==========================================
// 2. LER MEMÓRIA E GERAR ASSINATURA DE RESPOSTA
// ==========================================
const staticData = $getWorkflowStaticData('global');
const now = Math.floor(Date.now() / 1000);

const PARTNER_ID   = '2036495';
const PARTNER_KEY  = 'shpk484d63747246746b51744d69774445786c4b4a7363615156687448675379';
const SHOP_ID      = '762290009';
const ACCESS_TOKEN = staticData.access_token; // Lê o token fresco

// BLINDAGEM: sem token não há como assinar — falha cedo com mensagem clara em
// vez de enviar requisições 403 silenciosas para a Shopee.
if (!ACCESS_TOKEN) {
    throw new Error('access_token ausente no staticData — o nó Gerar Autenticação não renovou o token nesta execução.');
}

const path = '/api/v2/product/reply_comment'; 
const baseStr = PARTNER_ID + path + now + ACCESS_TOKEN + SHOP_ID;
const sign = hmacSha256(PARTNER_KEY, baseStr);

// ==========================================
// 3. ESTRUTURAR MENSAGENS
// ==========================================
// Formato exigido pela API reply_comment (corpo POST):
//   { "comment_list": [ { "comment_id": <int>, "comment": "<texto>" } ] }
// comment_id DEVE ser inteiro — string faz a API rejeitar o lote.
return $input.all().map(item => {
    const idComentario = Number(item.json.comment_id ?? item.json.cmt_id);

    return { 
        json: { 
            partner_id: parseInt(PARTNER_ID), 
            shop_id: parseInt(SHOP_ID), 
            access_token: ACCESS_TOKEN, 
            timestamp: now, 
            sign: sign, 
            comment_list: [
                {
                    comment_id: idComentario,
                    comment: item.json.resposta_gerada
                }
            ]
        } 
    };
});
